* Feedback network and loads (Fig. 24.31)
R1 vm Vout 10000.0
R2 vm Vin 10000.0
RL Vout 0 10000.0
CL Vout 0 1e-11

* Input sources: Vp at 0.5V common-mode, Vin pulse
Vref vp 0 DC 0.5
Vin Vin 0 DC 0.5 AC 1 PULSE(0.1 0.9 500n 1n 1n 50n 200n)

.control
* 1. Operating Point
op
let power = -i(VDD) * 1.8
print power

* 2. AC Open-Loop / Closed-Loop Response
ac dec 50 1 1G
let gain_db = vdb(Vout)
let phase = 180/PI * cph(v(Vout))
meas ac open_loop_dc_gain find gain_db at=10
meas ac unity_gain_frequency when gain_db=0 fall=1
meas ac phase_at_ugf find phase when gain_db=0 fall=1
let pm = 180 + phase_at_ugf
print pm

* 3. Transient Step Response
tran 0.1n 600n 490n
meas tran v_max max v(Vout)
meas tran v_min min v(Vout)
meas tran step_response_fall_time trig v(Vout) val=0.82 fall=1 targ v(Vout) val=0.18 fall=1
meas tran step_response_rise_time trig v(Vout) val=0.18 rise=1 targ v(Vout) val=0.82 rise=1
print open_loop_dc_gain unity_gain_frequency step_response_fall_time step_response_rise_time
quit
.endc
.end

